import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

/**
 * All dimensions in Millimeters (mm) for A4 Paper
 */
export const PAPER = {
  width: 210,
  height: 297,
};

export const CARD = {
  width: 63,
  height: 88,
};

export const GRID = {
  cols: 3,
  rows: 3,
  spacing: 5, // Gap between cards
};

// Calculated Margins to center 3x3 grid on A4
// Grid Total Width = (3 * 63) + (2 * 5) = 189 + 10 = 199mm
// Grid Total Height = (3 * 88) + (2 * 5) = 264 + 10 = 274mm
export const MARGIN = {
  left: (PAPER.width - (GRID.cols * CARD.width + (GRID.cols - 1) * GRID.spacing)) / 2,
  top: (PAPER.height - (GRID.rows * CARD.height + (GRID.rows - 1) * GRID.spacing)) / 2,
};

// Conversion factors
export const MM_TO_PX = 3.7795275591; // Approximation for preview rendering
export const CROP_MARK_SIZE = 5; // Length of crop marks in mm

export interface CardImage {
  id: string;
  name: string;
  dataUrl: string;
  type: string;
}

export interface PageLayout {
  pageNumber: number;
  cards: (CardImage | null)[]; // Max 9 cards
}

import { jsPDF } from 'jspdf';
import { PAPER, CARD, GRID, MARGIN, CROP_MARK_SIZE } from '../constants';
import { PageLayout } from '../types';

export const generatePDF = async (pages: PageLayout[]) => {
  const doc = new jsPDF({
    orientation: 'portrait',
    unit: 'mm',
    format: 'a4',
    compress: false // User requested high quality/no compression
  });

  pages.forEach((page, pageIdx) => {
    if (pageIdx > 0) doc.addPage();

    // Draw Crop Marks and Guides
    doc.setLineWidth(0.088); // Approx 0.25pt
    doc.setDrawColor(150, 150, 150);

    // Helper to draw a card slot
    page.cards.forEach((card, cardIdx) => {
      if (!card) return;

      const col = cardIdx % GRID.cols;
      const row = Math.floor(cardIdx / GRID.cols);

      const x = MARGIN.left + col * (CARD.width + GRID.spacing);
      const y = MARGIN.top + row * (CARD.height + GRID.spacing);

      // Add Image
      doc.addImage(card.dataUrl, 'JPEG', x, y, CARD.width, CARD.height, undefined, 'FAST');

      // Add Crop Marks at corners of each card
      // Corner Marks
      const markLen = CROP_MARK_SIZE;
      const offset = 2; // Marks start 2mm away from card edge

      // Top Left
      doc.line(x - offset, y, x - offset - markLen, y);
      doc.line(x, y - offset, x, y - offset - markLen);

      // Top Right
      doc.line(x + CARD.width + offset, y, x + CARD.width + offset + markLen, y);
      doc.line(x + CARD.width, y - offset, x + CARD.width, y - offset - markLen);

      // Bottom Left
      doc.line(x - offset, y + CARD.height, x - offset - markLen, y + CARD.height);
      doc.line(x, y + CARD.height + offset, x, y + CARD.height + offset + markLen);

      // Bottom Right
      doc.line(x + CARD.width + offset, y + CARD.height, x + CARD.width + offset + markLen, y + CARD.height);
      doc.line(x + CARD.width, y + CARD.height + offset, x + CARD.width, y + CARD.height + offset + markLen);
    });

    // Outer guide lines (optional but helpful)
    // Vertical exterior guides
    for (let c = 0; c <= GRID.cols; c++) {
      const x = MARGIN.left + c * (CARD.width + GRID.spacing) - (c > 0 && c < GRID.cols ? GRID.spacing/2 : 0);
      // Logic for lines that span full sheet height or just margin areas...
      // For simplicity, we stick to the crop marks around each card as they are more precise for MTG.
    }
  });

  doc.save('mtg-proxies-printable.pdf');
};

import { PAPER, CARD, GRID, MARGIN } from '../constants';
import { PageLayout } from '../types';

export const generateSVG = (pages: PageLayout[]) => {
  // We generate one SVG per page as most cutting software expects single files or specific sizing
  pages.forEach((page, pageIdx) => {
    const rects: string[] = [];

    page.cards.forEach((card, cardIdx) => {
      if (!card) return;

      const col = cardIdx % GRID.cols;
      const row = Math.floor(cardIdx / GRID.cols);

      const x = MARGIN.left + col * (CARD.width + GRID.spacing);
      const y = MARGIN.top + row * (CARD.height + GRID.spacing);

      rects.push(`<rect x="${x}" y="${y}" width="${CARD.width}" height="${CARD.height}" fill="none" stroke="black" stroke-width="0.1" />`);
    });

    const svgContent = `
<svg width="${PAPER.width}mm" height="${PAPER.height}mm" viewBox="0 0 ${PAPER.width} ${PAPER.height}" xmlns="http://www.w3.org/2000/svg">
  <g id="CutLines">
    ${rects.join('\n    ')}
  </g>
</svg>`;

    const blob = new Blob([svgContent], { type: 'image/svg+xml' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `mtg-cut-lines-page-${pageIdx + 1}.svg`;
    link.click();
    URL.revokeObjectURL(url);
  });
};

import React from 'react';
import { Trash2 } from 'lucide-react';
