interface CardPreviewProps {
  card: CardImage | null;
  onRemove?: () => void;
}

const CardPreview: React.FC<CardPreviewProps> = ({ card, onRemove }) => {
  const width = CARD.width * MM_TO_PX;
  const height = CARD.height * MM_TO_PX;

  return (
    <div 
      className="relative border-2 border-dashed border-slate-200 bg-slate-50 flex items-center justify-center overflow-hidden"
      style={{ width: `${width}px`, height: `${height}px` }}
    >
      {card ? (
        <>
          <img src={card.dataUrl} alt={card.name} className="w-full h-full object-cover" />
          {onRemove && (
            <button 
              onClick={onRemove}
              className="absolute top-1 right-1 p-1 bg-red-500 text-white rounded-full opacity-0 hover:opacity-100 transition-opacity"
            >
              <Trash2 size={14} />
            </button>
          )}
        </>
      ) : (
        <span className="text-slate-300 text-xs font-medium uppercase tracking-wider">Empty Slot</span>
      )}
    </div>
  );
};

