import { jsPDF } from 'jspdf';
import { PAPER, CARD, GRID, MARGIN } from '../constants';
import { PageLayout } from '../types';

export const generatePDF = async (pages: PageLayout[]) => {
  const doc = new jsPDF({
    orientation: 'portrait',
    unit: 'mm',
    format: 'a4',
    compress: false
  });

  pages.forEach((page, pageIdx) => {
    if (pageIdx > 0) doc.addPage();

    // Line settings for guides: very thin and light gray
    doc.setLineWidth(0.088); // Approx 0.25pt
    doc.setDrawColor(200, 200, 200);

    // 1. Draw VERTICAL guide lines (edge to edge)
    for (let col = 0; col < GRID.cols; col++) {
      const xStart = MARGIN.left + col * (CARD.width + GRID.spacing);
      const xEnd = xStart + CARD.width;

      // Line at the start of the card column
      doc.line(xStart, 0, xStart, PAPER.height);
      // Line at the end of the card column
      doc.line(xEnd, 0, xEnd, PAPER.height);
    }

    // 2. Draw HORIZONTAL guide lines (edge to edge)
    for (let row = 0; row < GRID.rows; row++) {
      const yStart = MARGIN.top + row * (CARD.height + GRID.spacing);
      const yEnd = yStart + CARD.height;

      // Line at the top of the card row
      doc.line(0, yStart, PAPER.width, yStart);
      // Line at the bottom of the card row
      doc.line(0, yEnd, PAPER.width, yEnd);
    }

    // 3. Draw the actual cards
    page.cards.forEach((card, cardIdx) => {
      if (!card) return;

      const col = cardIdx % GRID.cols;
      const row = Math.floor(cardIdx / GRID.cols);

      const x = MARGIN.left + col * (CARD.width + GRID.spacing);
      const y = MARGIN.top + row * (CARD.height + GRID.spacing);

      // Add Image - Using JPEG format for high compatibility
      // Note: We use 'FAST' alias for speed, but quality is maintained by no-compression setting in jsPDF constructor
      doc.addImage(card.dataUrl, 'JPEG', x, y, CARD.width, CARD.height, undefined, 'FAST');
    });
  });

  doc.save('mtg-proxies-professional-layout.pdf');
};
